            if hash_match == hash_value:
                return True
        return False

    def build_mappings(self, hashes):
        for hashed_password in hashes:
            if self.match_password(hashed_password, hashes):
                self.data[hashed_password].append(hash_to_index(hashed_password))

    def map_password(self, user_input):
        hashes = [self.data[user_input]]
